import { Component, createMemo, ParentComponent, Show, splitProps } from "solid-js";

import { Activatable, ActivatableProps } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { RingMeter } from "#core/ui-next/components/ring-meter.jsx";
import { LeaderInfo } from "#core/ui-next/screens/create-game/leader-select-model.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import style from "./leader-select-button.scss?url";

const LeaderXpRingComponent: Component<LeaderInfo> = (props) => {
	return (
		<Show when={props.level > 0 && !props.isLocked}>
			<RingMeter
				class="leader-button-ring-meter"
				value={props.currentXp}
				min={props.prevLevelXp}
				max={props.nextLevelXp}
				ringImage={'url("blp:leaderselect_xp_fill.png")'}
			>
				<div class="z-1 leader-button-ring-xp-bubble absolute bottom-0 -ml-4 left-1\/2 flex items-center justify-center text-sm font-white">
					{props.level}
				</div>
			</RingMeter>
		</Show>
	);
};

export const LeaderXpRing = ComponentRegistry.register("LeaderXpRing", LeaderXpRingComponent);

const LeaderPortraitComponent: Component<LeaderInfo> = (props) => {
	return (
		<Icon
			name={props.icon}
			context={props.icon == "LEADER_RANDOM" ? "CIRCLE_MASK" : "PORTRAIT_MASK"}
			class="leader-button-portrait"
		/>
	);
};

export const LeaderPortrait = ComponentRegistry.register("LeaderPortrait", LeaderPortraitComponent);

export interface LeaderSelectButtonBaseProps extends ActivatableProps {
	isLocked: boolean;
	isSelected: boolean;
	onFocus?: () => void;
	class?: string;
}

const LeaderSelectButtonBaseComponent: ParentComponent<LeaderSelectButtonBaseProps> = (props) => {
	return (
		<Activatable
			{...props}
			class={`leader-button-box flex items-center justify-center relative group -mx-2 ${props.class ?? ""}`}
			classList={{ locked: props.isLocked }}
			onFocus={props.onFocus}
			name="LeaderSelectButton"
		>
			<div class="absolute inset-0 flex items-center justify-center pointer-events-none">
				<div
					class="leader-button-focus opacity-0 group-focus\:opacity-100 group-hover\:opacity-100"
					classList={{ locked: props.isLocked }}
				/>
			</div>
			<div class="absolute inset-0 flex items-center justify-center pointer-events-none">
				<div
					class="leader-button-selection"
					classList={{ locked: props.isLocked, "opacity-0": !props.isSelected }}
				/>
			</div>
			{props.children}
			<div class="absolute inset-0 flex items-center justify-center pointer-events-none">
				<Show when={props.isLocked}>
					<div class="z-1 img-lock2 absolute bottom-0 size-8 -ml-4 left-1\/2 flex items-center justify-center text-sm font-white" />
				</Show>
			</div>
		</Activatable>
	);
};

export const LeaderSelectButtonBase = ComponentRegistry.register({
	name: "LeaderSelectButtonBase",
	createInstance: LeaderSelectButtonBaseComponent,
	styles: [style],
});

export interface LeaderSelectButtonProps extends ActivatableProps {
	isSelected: boolean;
	leaderInfo: LeaderInfo;
}

const LeaderSelectButtonComponent: Component<LeaderSelectButtonProps> = (props) => {
	const [local, other] = splitProps(props, ["isSelected", "leaderInfo", "onFocus"]);

	const leaderInfo = createMemo(() => local.leaderInfo);
	const isLocked = createMemo(() => leaderInfo().isLocked);

	const leaderNameShort = createMemo(() => {
		// Example: "LEADER_ADA_LOVELACE" -> "ada"
		// Special-case: "RANDOM" -> "random"
		let leaderName = local.leaderInfo.leaderID;
		if (leaderName?.toLowerCase() == "random") {
			return "random";
		} else {
			leaderName = leaderName.split("_")[1];
			return leaderName.toLowerCase();
		}
	});

	return (
		<AudioContextProvider
			segment="LeaderSelectPortraitButton"
			vars={{ leaderType: leaderNameShort() }}
		>
			<LeaderSelectButtonBaseComponent
				{...other}
				isLocked={isLocked()}
				isSelected={props.isSelected}
				onFocus={props.onFocus}
			>
				<div class="absolute inset-0 flex items-center justify-center pointer-events-none">
					<LeaderPortrait {...leaderInfo()} />
				</div>
				<div class="absolute inset-0 flex items-center justify-center pointer-events-none">
					<LeaderXpRing {...leaderInfo()} />
				</div>
			</LeaderSelectButtonBaseComponent>
		</AudioContextProvider>
	);
};

export const LeaderSelectButton = ComponentRegistry.register({
	name: "LeaderSelectButton",
	createInstance: LeaderSelectButtonComponent,
	styles: [style],
});
